mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { decideWhatsApp } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-dev2-haiku/work/ours-g5-3/bot.mjs';

const T0 = 1767272400; // 2026-01-01T13:00:00Z, Meta's seconds timestamp
const at = (sec) => new Date(sec * 1000);
const H = 3600;
const text = (inbound, optedIn = true) => ({ type: 'text', contact: { optedIn, lastInboundTimestamp: inbound } });
const tpl = (inbound, optedIn = true) => ({ type: 'template', contact: { optedIn, lastInboundTimestamp: inbound } });
const ok = { allowed: true, reason: null };

// Text inside the window
assert.deepEqual(decideWhatsApp(text(String(T0)), at(T0 + 1)), ok);
assert.deepEqual(decideWhatsApp(text(String(T0)), at(T0 + 23 * H + 3599)), ok);
// Window boundary: exactly 24h closes it
assert.deepEqual(decideWhatsApp(text(String(T0)), at(T0 + 24 * H)), { allowed: false, reason: 'outside_service_window' });
assert.deepEqual(decideWhatsApp(text(String(T0)), at(T0 + 25 * H)), { allowed: false, reason: 'outside_service_window' });
// Never written to us
assert.deepEqual(decideWhatsApp(text(null), at(T0)), { allowed: false, reason: 'outside_service_window' });
// Templates are allowed outside the window, and with no inbound history
assert.deepEqual(decideWhatsApp(tpl(String(T0)), at(T0 + 100 * H)), ok);
assert.deepEqual(decideWhatsApp(tpl(null), at(T0)), ok);
// Opt-in is checked first, for both types
assert.deepEqual(decideWhatsApp(text(String(T0), false), at(T0 + 1)), { allowed: false, reason: 'not_opted_in' });
assert.deepEqual(decideWhatsApp(tpl(null, false), at(T0)), { allowed: false, reason: 'not_opted_in' });
assert.deepEqual(decideWhatsApp({ type: 'template', contact: { lastInboundTimestamp: null } }, at(T0)), { allowed: false, reason: 'not_opted_in' });
// Unknown type
assert.deepEqual(decideWhatsApp({ type: 'image', contact: { optedIn: true, lastInboundTimestamp: null } }, at(T0)), { allowed: false, reason: 'unknown_message_type' });
// Bad timestamps fail closed
assert.deepEqual(decideWhatsApp(text('abc'), at(T0)), { allowed: false, reason: 'invalid_inbound_timestamp' });
assert.deepEqual(decideWhatsApp(text(''), at(T0)), { allowed: false, reason: 'invalid_inbound_timestamp' });
assert.deepEqual(decideWhatsApp(text(String(T0 + 60)), at(T0)), { allowed: false, reason: 'invalid_inbound_timestamp' });
// Numeric timestamp is accepted the same way as the string form
assert.deepEqual(decideWhatsApp(text(T0), at(T0 + 1)), ok);
console.log('all checks passed');
EOF
